function makeTower(type,r,c){const g=new THREE.Group(),color=types[type].color;g.userData={r,c,type,pulse:0};box(g,0,.15,0,1.28,.3,1.28,0x506c5c);box(g,0,.4,0,1.1,.2,1.1,color);if(type===0){box(g,0,.95,0,1.05,.9,1.05,0x76553d);box(g,0,1.45,0,1.2,.18,1.2,color);box(g,0,1.56,0,.7,.08,.7,0xffd2a2,true);for(const x of [-.49,.49])box(g,x,.95,.55,.12,.8,.12,color);}if(type===1){box(g,0,.8,0,1.2,.75,1,0x687c85);box(g,0,1.23,0,1.3,.16,1.1,color);for(const x of [-.4,.4])box(g,x,1.4,0,.25,.3,.6,color,true);}if(type===2){box(g,0,.95,0,.72,1.1,.72,0x547561);box(g,0,1.65,0,1.05,.3,1.05,color);box(g,0,2.0,0,.32,.6,.32,color,true);box(g,-.38,1.98,0,.18,.6,.18,0xb9e6c2);box(g,.38,2.15,0,.18,.9,.18,0xb9e6c2);box(g,0,2.4,0,1,.15,.3,color);}if(type===3){box(g,0,.8,0,.85,.7,.85,0x6f6484);const gem=box(g,0,1.55,0,.7,.7,.7,color,true);gem.rotation.z=Math.PI/4;gem.rotation.y=Math.PI/4;box(g,0,2.15,0,1.2,.1,1.2,color,true);}g.position.set(startX+c*spacing,.27,rows[r]);scene.add(g);return g;}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function sync(){ $('#money').textContent=state.money;$('#health').textContent=state.health;$('#health-fill').style.width=state.health+'%';$('#wave').textContent=String(state.wave).padStart(2,'0');$('#bpm').textContent=state.bpm;$('#bar-count').textContent='LOOP '+String(state.loop).padStart(2,'0');$('#play').innerHTML=(state.playing?'Ⅱ <span>暂停试听</span>':'▶ <span>试听循环</span>');document.body.classList.toggle('playing',state.playing);for(const cell of document.querySelectorAll('.seq-cell')){const key=Number(cell.dataset.key),t=towers.get(key);cell.classList.toggle('on',!!t);cell.classList.toggle('current',Number(cell.dataset.c)===state.step&&state.playing);if(t)cell.style.setProperty('--note',types[t.userData.type].css);cell.setAttribute('aria-label',`第${Number(cell.dataset.r)+1}行 第${Number(cell.dataset.c)+1}拍 ${t?types[t.userData.type].name:'空格'}`);cell.setAttribute('aria-pressed',!!t);} }
function place(r,c,type=state.selected,free=false){const key=r*16+c;if(towers.has(key))return;if(!free&&state.money<types[type].cost){toast('回响碎片不足 · 击败怪物可获得更多碎片');return;}if(!free)state.money-=types[type].cost;towers.set(key,makeTower(type,r,c));sync();}
function remove(r,c){const key=r*16+c,t=towers.get(key);if(!t)return;state.money+=Math.floor(types[t.userData.type].cost*.75);scene.remove(t);towers.delete(key);sync();}
for(let r=0;r<4;r++)for(let c=0;c<16;c++){const b=document.createElement('button');b.className='seq-cell';b.dataset.key=r*16+c;b.dataset.r=r;b.dataset.c=c;b.onclick=()=>{begin();const key=r*16+c;if(towers.has(key))remove(r,c);else{place(r,c);soundNote(state.selected,r,.14);}};b.oncontextmenu=e=>{e.preventDefault();remove(r,c);};$('#sequencer').appendChild(b);}
