// Synthesized entirely in the browser: no recordings or remote audio required.
let audio=null,master=null,muted=true,noiseBuffer=null;
function initAudio(){if(audio){audio.resume();return;}audio=new(window.AudioContext||window.webkitAudioContext)();master=audio.createGain();master.gain.value=muted?0:.38;const compressor=audio.createDynamicsCompressor();compressor.threshold.value=-15;compressor.ratio.value=6;master.connect(compressor);compressor.connect(audio.destination);noiseBuffer=audio.createBuffer(1,audio.sampleRate*.3,audio.sampleRate);const data=noiseBuffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;}
function setMuted(m){muted=m;initAudio();master.gain.setTargetAtTime(m?0:.38,audio.currentTime,.03);$('#sound').innerHTML=`${m?'♩':'♫'} <span>声音${m?'关闭':'开启'}</span>`;}
function soundNote(type,row,duration=.22){if(!audio||muted)return;const now=audio.currentTime,g=audio.createGain();g.connect(master);const pan=audio.createStereoPanner();pan.pan.value=(row-1.5)*.22;pan.connect(g);if(type===0){const osc=audio.createOscillator();osc.frequency.setValueAtTime(150,now);osc.frequency.exponentialRampToValueAtTime(43,now+.12);g.gain.setValueAtTime(.9,now);g.gain.exponentialRampToValueAtTime(.001,now+.26);osc.connect(pan);osc.start(now);osc.stop(now+.28);}else if(type===1){const noise=audio.createBufferSource();noise.buffer=noiseBuffer;const hp=audio.createBiquadFilter();hp.type='highpass';hp.frequency.value=1500;noise.connect(hp);hp.connect(pan);g.gain.setValueAtTime(.3,now);g.gain.exponentialRampToValueAtTime(.001,now+.14);noise.start(now);noise.stop(now+.16);}else{const freq=[293.66,329.63,440,493.88][row]*(type===3?.25:1);const osc=audio.createOscillator();osc.type=type===3?'triangle':'sine';osc.frequency.value=freq;osc.connect(pan);g.gain.setValueAtTime(0,now);g.gain.linearRampToValueAtTime(type===3?.45:.32,now+.009);g.gain.exponentialRampToValueAtTime(.001,now+(type===3?.65:.9));osc.start(now);osc.stop(now+1.05);if(type===2){const overtone=audio.createOscillator(),og=audio.createGain();overtone.type='sine';overtone.frequency.value=freq*2;og.gain.setValueAtTime(.09,now);og.gain.exponentialRampToValueAtTime(.001,now+.34);overtone.connect(og);og.connect(pan);overtone.start(now);overtone.stop(now+.4);}}}
const enemies=[],effects=[];let waveClock=0,spawnClock=0,nextStep=0,autoNext=0;
function burst(pos,color,count=7){for(let i=0;i<count;i++){const m=box(scene,pos.x,pos.y,pos.z,.11,.11,.11,color,true);effects.push({mesh:m,life:.6,max:.6,velocity:new THREE.Vector3((Math.random()-.5)*4,Math.random()*3+1,(Math.random()-.5)*4)});}}
function beam(from,to,color){const direction=new THREE.Vector3().subVectors(to,from);const m=new THREE.Mesh(new THREE.BoxGeometry(.06,.06,direction.length()),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.9}));m.position.copy(from).add(to).multiplyScalar(.5);m.quaternion.setFromUnitVectors(new THREE.Vector3(0,0,1),direction.normalize());scene.add(m);effects.push({mesh:m,life:.18,max:.18,ownGeometry:true});}
function ripple(pos,color){const g=new THREE.RingGeometry(.8,1,24);g.rotateX(-Math.PI/2);const m=new THREE.Mesh(g,new THREE.MeshBasicMaterial({color,transparent:true,opacity:.7,side:THREE.DoubleSide,depthWrite:false}));m.position.copy(pos);m.position.y=.35;scene.add(m);effects.push({mesh:m,life:.55,max:.55,ripple:true,ownGeometry:true});}
function spawnEnemy(){const g=new THREE.Group(),strong=state.wave>=3&&state.spawned%4===0;box(g,0,.8,0,.65,.85,.45,strong?0x786384:0x537467);const head=box(g,0,1.48,0,.63,.58,.59,strong?0x9c8ca4:0x90a889);for(const z of [-.18,.18])box(g,.325,1.5,z,.035,.09,.10,0xf1cb92,true);const arms=[];for(const z of [-.43,.43])arms.push(box(g,.1,.93,z,.35,.7,.23,0x69816e));const legs=[];for(const z of [-.18,.18])legs.push(box(g,0,.22,z,.3,.48,.23,0x4e5b65));if(strong){g.scale.setScalar(1.25);box(g,0,1.85,0,.85,.2,.75,0x685574);}g.position.set(-27,.1,(rand()-.5)*1.7);scene.add(g);const hp=(48+state.wave*14)*(strong?1.8:1);enemies.push({mesh:g,hp,maxHp:hp,speed:1.25+state.wave*.17,slow:0,arms,legs,offset:rand()*10,hit:0});state.spawned++;}
function fire(tower){const u=tower.userData,conf=types[u.type];u.pulse=1;soundNote(u.type,u.r);const targets=enemies.filter(e=>e.hp>0&&e.mesh.position.distanceTo(tower.position)<conf.range).sort((a,b)=>b.mesh.position.x-a.mesh.position.x);if(!targets.length)return;const hit=u.type===2?targets.slice(0,1):targets.slice(0,u.type===0?4:3);if(u.type!==2)ripple(tower.position,conf.color);for(const enemy of hit){enemy.hp-=conf.damage;enemy.hit=.16;if(u.type===3)enemy.slow=1.8;if(u.type===0)enemy.mesh.position.x-=.42;beam(tower.position.clone().add(new THREE.Vector3(0,1.6,0)),enemy.mesh.position.clone().add(new THREE.Vector3(0,1,0)),conf.color);if(enemy.hp<=0){state.money+=8;state.kills++;burst(enemy.mesh.position.clone().add(new THREE.Vector3(0,1,0)),conf.color,9);}}}
function step(){state.step=(state.step+1)%16;if(state.step===0&&state.loop<999)state.loop++;for(const tower of towers.values())if(tower.userData.c===state.step)fire(tower);sync();}
function begin(){if(state.ended)return;if(!state.started){state.started=true;$('#intro').classList.add('dismissed');$('#intro').inert=true;setMuted(false);setPlaying(true);toast('预置旋律已就绪 · 点击基座建造，或直接迎接暗潮');}}
function setPlaying(p){if(state.fighting&&!p){toast('暗潮来袭时，防线必须保持演奏');return;}initAudio();state.playing=p;if(p)nextStep=performance.now()/1000;sync();}
function launchWave(){begin();if(state.fighting||state.ended)return;state.wave++;state.fighting=true;state.spawned=0;waveClock=0;spawnClock=0;autoNext=0;state.money+=45;state.playing=true;nextStep=performance.now()/1000;$('#phase-label').textContent='DEFEND THE RESONANCE';$('#phase-name').textContent=`第 ${state.wave} 波 · 暗潮来袭`;$('#phase-desc').textContent='保持旋律，守护共鸣之心。';$('#wave-start').disabled=true;$('#wave-start').textContent='暗潮进行中…';toast(`第 ${state.wave} 波暗潮来袭 · 补给 +45 碎片`);sync();}
function end(won){state.ended=true;state.fighting=false;state.playing=false;document.exitPointerLock?.();$('#result-tag').textContent=won?'THE VALLEY REMEMBERS':'A NEW MELODY AWAITS';$('#result-title').textContent=won?'原野记住了你的旋律。':'最后一声回响，仍未消散。';$('#result-text').textContent=`${won?'你守住了全部五波暗潮！':'共鸣核心已失守。试着在路线末端增加旋律箭塔。'} 共击败 ${state.kills} 个暗潮生物，完成 ${state.loop} 次旋律循环。`;$('#result-dialog').showModal();sync();}
