$('#start').onclick=begin;$('#wave-start').onclick=launchWave;$('#sound').onclick=()=>setMuted(!muted);$('#play').onclick=()=>{const wasStarted=state.started;begin();if(wasStarted)setPlaying(!state.playing);};$('#view').onclick=toggleView;
$('#slower').onclick=()=>{state.bpm=Math.max(60,state.bpm-6);sync();};$('#faster').onclick=()=>{state.bpm=Math.min(168,state.bpm+6);sync();};
