addEventListener('keydown',e=>{if(['INPUT','TEXTAREA'].includes(e.target.tagName)||e.target.isContentEditable||$('dialog[open]'))return;if(e.code==='Space'){e.preventDefault();const wasStarted=state.started;begin();if(wasStarted)setPlaying(!state.playing);}if(e.code==='KeyV')toggleView();if(['Digit1','Digit2','Digit3','Digit4'].includes(e.code))select(Number(e.code.slice(-1))-1);keys.add(e.code);});addEventListener('keyup',e=>keys.delete(e.code));addEventListener('blur',()=>keys.clear());
