  nightMix=THREE.MathUtils.lerp(nightMix,state.fighting?1:0,dt*.3);scene.background.copy(daylight).lerp(nightfall,nightMix);scene.fog.color.copy(scene.background);sun.intensity=3.2-nightMix*1.7;ambient.intensity=2.1-nightMix*.65;crystal.rotation.y=time*.4;crystal.position.y=2.8+Math.sin(time*1.7)*.16;ring.rotation.y=time*.12;coreLight.intensity=10+Math.sin(time*2)*2;portal.scale.z=1+Math.sin(time*2)*.035;fireflies.position.y=Math.sin(time*.3)*.15;
  if(state.playing&&!state.ended){if(now>=nextStep){step();nextStep=now+60/state.bpm/4;}const fraction=1-(nextStep-now)/(60/state.bpm/4);const x=startX+(state.step+fraction)*spacing;scanner.visible=true;scanLine.visible=true;scanner.position.x=scanLine.position.x=x;}else{scanner.visible=scanLine.visible=false;}
